-- Generated by scripts/build_compiled.py from src/fraudrules/rules/foreign-agent/fa-006-same-day-pass-through-abroad.yaml. Do not edit.
-- FA-006 Funds credited to an MSB account leave for a foreign third party within a day
SELECT DISTINCT
  'FA-006' AS rule_id,
  'transactions' AS anchor_table,
  s1.id AS anchor_id
FROM transactions AS s1
JOIN transactions AS s0
  ON s0.account_id = s1.account_id
  AND s0.ts < s1.ts
  AND s0.ts > s1.ts - 86400
  AND (
    s0.direction = 'in' AND s0.amount_cents >= 1000000
  )
WHERE
  (
    s1.direction = 'out'
    AND s1.channel = 'wire'
    AND s1.amount_cents >= 1000000
    AND s1.counterparty_country <> 'us'
    AND NOT COALESCE(s1.in_agent_agreement = 1, FALSE)
    AND (
      NOT s1.directing_agent_id IS NULL OR s1.customer_segment = 'msb'
    )
  );
